{
  "cvars": {
    "ivs": [
      {
        "description": "Applicant gender: 1 if applicant is female, 0 if male (primary independent variable of interest).",
        "columns": [
          "female"
        ]
      }
    ],
    "dv": {
      "description": "Mortgage application outcome: 1 if application was accepted, 0 if denied (dependent variable).",
      "columns": [
        "accept"
      ]
    },
    "controls": [
      {
        "description": "Applicant race: 1 if applicant is Black, 0 otherwise. Included to adjust for race differences in approval rates.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "black"
        ]
      },
      {
        "description": "Applicant self-employment indicator: 1 if self-employed, 0 otherwise. Controls for employment type.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "self_employed"
        ]
      },
      {
        "description": "Marital status: 1 if married, 0 otherwise. Controls for household composition and joint income effects.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "married"
        ]
      },
      {
        "description": "Applicant has a bad credit history: 1 if history of bad credit, 0 otherwise. Controls for credit problems.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "bad_history"
        ]
      },
      {
        "description": "Mortgage credit score (standardized). Ordinal measure of mortgage creditworthiness; standardized to mean 0 SD 1 for modeling.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "mortgage_credit_z"
        ]
      },
      {
        "description": "Consumer credit score (standardized). Ordinal measure of consumer creditworthiness; standardized to mean 0 SD 1 for modeling.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "consumer_credit_z"
        ]
      },
      {
        "description": "Total debt payments to income ratio (PI_ratio), standardized. Controls for ability to repay.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "PI_ratio_z"
        ]
      },
      {
        "description": "Loan-to-value ratio, standardized. Controls for loan risk relative to property value.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "loan_to_value_z"
        ]
      },
      {
        "description": "Housing expense as a ratio of income (standardized). Controls for housing cost burden.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "housing_expense_ratio_z"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Transformations performed:\n    - Keep a copy of the dataframe.\n    - Drop rows with missing values in any columns required for the model.\n    - Coerce relevant columns to numeric and drop rows that become NA after coercion.\n    - Create z-scored (standardized) versions of continuous/ordinal predictors used as controls:\n      mortgage_credit_z, consumer_credit_z, PI_ratio_z, loan_to_value_z, housing_expense_ratio_z.\n    - Ensure binary indicator columns are integer-typed.\n\n    Returns the transformed dataframe containing at least the columns used in the model.\n    \"\"\"\n    df = df.copy()\n\n    # Columns required for modeling\n    required_cols = [\n        'accept', 'female', 'black', 'self_employed', 'married', 'bad_history',\n        'mortgage_credit', 'consumer_credit', 'PI_ratio', 'loan_to_value', 'housing_expense_ratio'\n    ]\n\n    # Drop rows missing any required columns\n    df = df.dropna(subset=required_cols)\n\n    # Coerce to numeric where appropriate (safe guard if strings present)\n    for c in required_cols:\n        df[c] = pd.to_numeric(df[c], errors='coerce')\n\n    # Drop rows that could not be coerced\n    df = df.dropna(subset=required_cols)\n\n    # Standardize continuous / ordinal predictors (z-score). Use population std (ddof=0) for stability.\n    to_z = ['mortgage_credit', 'consumer_credit', 'PI_ratio', 'loan_to_value', 'housing_expense_ratio']\n    for c in to_z:\n        zcol = f\"{c}_z\"\n        mean = df[c].mean()\n        std = df[c].std(ddof=0)\n        # If std is zero (unlikely), set z to zero to avoid division by zero\n        if std == 0 or np.isnan(std):\n            df[zcol] = 0.0\n        else:\n            df[zcol] = (df[c] - mean) / std\n\n    # Ensure binary indicators are integer type (0/1)\n    binary_cols = ['accept', 'female', 'black', 'self_employed', 'married', 'bad_history']\n    for c in binary_cols:\n        df[c] = df[c].astype(int)\n\n    # Return dataframe containing all columns needed by the model\n    # (original binary columns plus standardized controls)\n    return df\n",
  "m_code": "def model(df: pd.DataFrame):\n    \"\"\"\n    Fit a logistic regression to estimate the association between applicant gender and mortgage acceptance.\n\n    Model specification (primary):\n      accept ~ female + black + self_employed + married + bad_history\n               + mortgage_credit_z + consumer_credit_z + PI_ratio_z + loan_to_value_z + housing_expense_ratio_z\n\n    - Uses statsmodels.Logit; if Logit fails to converge or faces issues, falls back to GLM with Binomial family.\n    - Returns the fitted results object (statsmodels results instance).\n    \"\"\"\n    df = df.copy()\n\n    # Outcome and predictors used in model (must match columns created in transform)\n    y = df['accept']\n    X_cols = [\n        'female', 'black', 'self_employed', 'married', 'bad_history',\n        'mortgage_credit_z', 'consumer_credit_z', 'PI_ratio_z', 'loan_to_value_z', 'housing_expense_ratio_z'\n    ]\n\n    X = df[X_cols]\n\n    # Add constant for intercept\n    X = sm.add_constant(X, has_constant='add')\n\n    # Fit logistic regression; provide robust fall-back if needed\n    try:\n        logit = sm.Logit(y, X)\n        results = logit.fit(disp=False)\n    except Exception:\n        glm = sm.GLM(y, X, family=sm.families.Binomial())\n        results = glm.fit()\n\n    return results\n"
}
